INSERT  IGNORE INTO `updates` VALUES (1,'2025-12-15 01:52:05','Operations','We\'re in contact with the vendor to repair the fridge. It\'ll be ready soon!\n\nThanks for reporting the issues!\n\nStay tuned for more updates.',10,'2025-12-15 09:52:04','2025-12-15 09:52:04'),(2,'2025-12-13 01:52:05','Choon Heng','Update: we solved the light issue. It should be working well now.\n\nWe\'re looking into the complaints about the fridge. Stay tuned for any updates.\n\nCheers!',9,'2025-12-15 09:52:04','2025-12-15 09:52:04'),(3,'2025-12-11 01:52:05','Facilities','Floor markings have been refreshed across the hall.\n\nNew cleaning schedule is in place to reduce dust.\n\nReport any issues via spill and we\'ll take a look.',8,'2025-12-15 09:52:04','2025-12-15 09:52:04');
